function withUser(Comp) {
  return function WithUser(props) {
    const user = useUser();
    return (
      <Comp {...props} user={user} />
    );
  };
}

const Profile2 = withUser(Profile);

function Page() {
  // 🔴 New component type every render
  const P = withUser(Profile);
  return <P />;
}

function Profile() {
  const user = useUser();
  return <h1>{user.name}</h1>;
}
